CREATE TABLE public.ajo_members (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    ajo_id uuid NOT NULL,
    user_id uuid NOT NULL,
    position_id uuid,
    invitation_id uuid,
    status public.member_status DEFAULT 'invited'::public.member_status NOT NULL,
    invited_at timestamp with time zone DEFAULT now() NOT NULL,
    joined_at timestamp with time zone,
    left_at timestamp with time zone,
    exit_reason text,
    replaced_by_membership_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ajo_members_active_joined CHECK (((status <> ALL (ARRAY['active'::public.member_status, 'defaulted'::public.member_status, 'replaced'::public.member_status, 'exited'::public.member_status, 'removed'::public.member_status])) OR (joined_at IS NOT NULL)))
);


