CREATE TABLE public.ajo_positions (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    ajo_id uuid NOT NULL,
    position_number smallint NOT NULL,
    status public.position_status DEFAULT 'open'::public.position_status NOT NULL,
    preference_rank smallint,
    locked_at timestamp with time zone,
    released_at timestamp with time zone,
    release_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ajo_positions_locked_has_timestamp CHECK (((status <> 'locked'::public.position_status) OR (locked_at IS NOT NULL))),
    CONSTRAINT ajo_positions_position_number_check CHECK ((position_number >= 1)),
    CONSTRAINT ajo_positions_preference_rank_check CHECK (((preference_rank IS NULL) OR (preference_rank >= 1))),
    CONSTRAINT ajo_positions_released_has_reason CHECK (((released_at IS NULL) OR (release_reason IS NOT NULL)))
);


--

--

COMMENT ON TABLE public.ajo_positions IS 'The turn order. Occupancy is NOT held here -- ajo_members.position_id is the single source of truth, which removes a circular foreign key and means a position can be released without touching its own row. See section 8.2.';


