CREATE TABLE public.ajos (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    reference text DEFAULT ('AJO-'::text || upper(substr(replace((app.uuidv7())::text, '-'::text, ''::text), 1, 12))) NOT NULL,
    name text NOT NULL,
    description text,
    status public.ajo_status DEFAULT 'draft'::public.ajo_status NOT NULL,
    organizer_user_id uuid NOT NULL,
    currency character(3) DEFAULT 'NGN'::bpchar NOT NULL,
    contribution_amount_kobo bigint NOT NULL,
    frequency_id uuid NOT NULL,
    preferred_channel_id uuid,
    position_count smallint NOT NULL,
    total_rounds smallint DEFAULT 2 NOT NULL,
    rounds_completed smallint DEFAULT 0 NOT NULL,
    enrollment_opens_at timestamp with time zone DEFAULT now() NOT NULL,
    enrollment_closes_at timestamp with time zone NOT NULL,
    activated_at timestamp with time zone,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancellation_reason text,
    frozen_at timestamp with time zone,
    freeze_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ajos_activated_has_timestamp CHECK (((status <> ALL (ARRAY['active'::public.ajo_status, 'round_in_progress'::public.ajo_status, 'completed'::public.ajo_status])) OR (activated_at IS NOT NULL))),
    CONSTRAINT ajos_cancelled_has_reason CHECK (((status <> ALL (ARRAY['cancelled'::public.ajo_status, 'cancelling'::public.ajo_status])) OR (cancellation_reason IS NOT NULL))),
    CONSTRAINT ajos_check CHECK (((rounds_completed >= 0) AND (rounds_completed <= total_rounds))),
    CONSTRAINT ajos_completed_has_timestamp CHECK (((status <> 'completed'::public.ajo_status) OR (completed_at IS NOT NULL))),
    CONSTRAINT ajos_contribution_amount_kobo_check CHECK ((contribution_amount_kobo > 0)),
    CONSTRAINT ajos_currency_check CHECK ((currency = 'NGN'::bpchar)),
    CONSTRAINT ajos_enrollment_window_is_bounded CHECK ((enrollment_closes_at >= enrollment_opens_at)),
    CONSTRAINT ajos_enrollment_window_is_five_days CHECK ((enrollment_closes_at <= (enrollment_opens_at + '5 days'::interval))),
    CONSTRAINT ajos_frozen_has_reason CHECK (((status <> 'frozen'::public.ajo_status) OR ((frozen_at IS NOT NULL) AND (freeze_reason IS NOT NULL)))),
    CONSTRAINT ajos_name_check CHECK (((length(btrim(name)) >= 3) AND (length(btrim(name)) <= 80))),
    CONSTRAINT ajos_position_count_check CHECK ((position_count >= 2)),
    CONSTRAINT ajos_total_rounds_check CHECK ((total_rounds >= 2))
);


--

--

COMMENT ON COLUMN public.ajos.contribution_amount_kobo IS 'The base obligation, in kobo. A member owing NGN 1,000.00 has contribution_amount_kobo = 100000. The 2% fee is never added here: the fee is a charge on the member, not a change to what the pool receives.';


