CREATE TABLE public.contribution_frequencies (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    code text NOT NULL,
    label text NOT NULL,
    interval_count smallint NOT NULL,
    interval_unit text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order smallint DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT contribution_frequencies_interval_count_check CHECK ((interval_count > 0)),
    CONSTRAINT contribution_frequencies_interval_unit_check CHECK ((interval_unit = ANY (ARRAY['day'::text, 'week'::text, 'month'::text])))
);


