CREATE TABLE public.contribution_schedules (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    round_id uuid NOT NULL,
    ajo_id uuid NOT NULL,
    due_date date NOT NULL,
    expected_amount_kobo bigint NOT NULL,
    expected_member_count smallint NOT NULL,
    late_cutoff_at timestamp with time zone NOT NULL,
    grace_ends_at timestamp with time zone,
    status public.schedule_status DEFAULT 'draft'::public.schedule_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT contribution_schedules_expected_amount_kobo_check CHECK ((expected_amount_kobo > 0)),
    CONSTRAINT contribution_schedules_expected_member_count_check CHECK ((expected_member_count >= 0)),
    CONSTRAINT contribution_schedules_grace_after_cutoff CHECK (((grace_ends_at IS NULL) OR (grace_ends_at >= late_cutoff_at)))
);


