CREATE TABLE public.payment_channels (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    code text NOT NULL,
    label text NOT NULL,
    provider text NOT NULL,
    provider_channel_code text NOT NULL,
    min_amount_kobo bigint DEFAULT 0 NOT NULL,
    max_amount_kobo bigint,
    requires_reference boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT payment_channels_check CHECK (((max_amount_kobo IS NULL) OR (max_amount_kobo >= min_amount_kobo))),
    CONSTRAINT payment_channels_min_amount_kobo_check CHECK ((min_amount_kobo >= 0))
);


