CREATE TABLE public.rounds (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    ajo_id uuid NOT NULL,
    round_number smallint NOT NULL,
    status public.round_status DEFAULT 'scheduled'::public.round_status NOT NULL,
    due_date date NOT NULL,
    opens_at timestamp with time zone NOT NULL,
    closes_at timestamp with time zone NOT NULL,
    target_amount_kobo bigint NOT NULL,
    base_pool_kobo bigint DEFAULT 0 NOT NULL,
    fee_collected_kobo bigint DEFAULT 0 NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    held_at timestamp with time zone,
    held_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT rounds_base_pool_kobo_check CHECK ((base_pool_kobo >= 0)),
    CONSTRAINT rounds_completed_has_timestamp CHECK (((status <> 'completed'::public.round_status) OR (completed_at IS NOT NULL))),
    CONSTRAINT rounds_fee_collected_kobo_check CHECK ((fee_collected_kobo >= 0)),
    CONSTRAINT rounds_held_has_reason CHECK (((status <> 'held'::public.round_status) OR (held_reason IS NOT NULL))),
    CONSTRAINT rounds_round_number_check CHECK ((round_number >= 1)),
    CONSTRAINT rounds_target_amount_kobo_check CHECK ((target_amount_kobo > 0))
);


